TLM.f("Tempora/Quad6-1",{"officium":"Feria Secunda Majoris Hebdomadæ","rule":["no Gloria","Suffragium=Ecclesiæ,Papa;;","Prefatio=Quad5","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad5","Prelude","Passio","omit commemoratio incipit","no Ultima Evangelium"],"fallback":"Tempora/Quad6-0r","from":{"Munda Cor Passionis":"Tempora/Quad6-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 34:1-2"},{"k":"text","la":"Júdica, Dómine, nocéntes me, expúgna impugnántes me: apprehénde arma et scutum, et exsúrge in adjutórium meum, Dómine, virtus salútis meæ."},{"k":"ref","la":"Ps 34:3"},{"k":"text","la":"Effúnde frámeam, et conclúde advérsus eos, qui persequúntur me: dic ánimæ meæ: Salus tua ego sum."},{"k":"text","la":"Júdica, Dómine, nocéntes me, expúgna impugnántes me: apprehénde arma et scutum, et exsúrge in adjutórium meum, Dómine, virtus salútis meæ."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, omnípotens Deus: ut, qui in tot advérsis ex nostra infirmitáte defícimus; intercedénte unigéniti Fílii tui passióne respirémus:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Isa 50:5-10"},{"k":"text","la":"In diébus illis: Dixit Isaías: Dóminus Deus apéruit mihi aurem, ego autem non contradíco: retrórsum non ábii. Corpus meum dedi percutiéntibus et genas meas velléntibus: fáciem meam non avérti ab increpántibus et conspuéntibus in me. Dóminus Deus auxiliátor meus, ídeo non sum confúsus: ídeo posui fáciem meam ut petram duríssimam, et scio, quóniam non confúndar. Juxta est, qui justíficat me, quis contradícet mihi? Stemus simul, quis est adversárius meus? Accédat ad me. Ecce, Dóminus Deus auxiliátor meus: quis est, qui condémnet me? Ecce, omnes quasi vestiméntum conteréntur, tinea cómedet eos. Quis ex vobis timens Dóminum, áudiens vocem servi sui? Qui ambulávit in ténebris, et non est lumen ei, speret in nómine Dómini, et innitátur super Deum suum."}],"Graduale":[{"k":"ref","la":"Ps 34:23 et 3"},{"k":"text","la":"Exsúrge, Dómine, et inténde judício meo, Deus meus et Dóminus meus, in causam meam."},{"k":"text","la":"Effúnde frámeam, et conclúde advérsus eos, qui me persequúntur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 12:1-9"},{"k":"text","la":"Ante sex dies Paschæ venit Jesus Bethániam, ubi Lázarus fúerat mórtuus, quem suscitávit Jesus. Fecérunt autem ei cenam ibi: et Martha ministrábat, Lázarus vero unus erat ex discumbéntibus cum eo. María ergo accépit libram unguénti nardi pístici pretiósi, et unxit pedes Jesu, et extérsit pedes ejus capíllis suis: et domus impléta est ex odóre unguénti. Dixit ergo unus ex discípulis ejus, Judas Iscariótes, qui erat eum traditúrus: Quare hoc unguéntum non véniit trecéntis denáriis, et datum est egénis? Dixit autem hoc, non quia de egénis pertinébat ad eum, sed quia fur erat, et lóculos habens, ea, quæ mittebántur, portábat. Dixit ergo Jesus: Sínite illam, ut in diem sepultúræ meæ servet illud. Páuperes enim semper habétis vobíscum: me autem non semper habétis. Cognóvit ergo turba multa ex Judǽis, quia illic est: et venérunt, non propter Jesum tantum, sed ut Lázarum vidérent, quem suscitávit a mórtuis."}],"Offertorium":[{"k":"ref","la":"Ps 142:9-10"},{"k":"text","la":"Eripe me de inimícis meis, Dómine: ad te confúgi, doce me fácere voluntátem tuam: quia Deus meus es tu."}],"Secreta":[{"k":"text","la":"Hæc sacrifícia nos, omnípotens Deus, poténti virtúte mundátos, ad suum fáciant purióres veníre princípium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 34:26"},{"k":"text","la":"Erubéscant et revereántur simul, qui gratulántur malis meis: induántur pudóre et reveréntia, qui malígna loquúntur advérsus me."}],"Postcommunio":[{"k":"text","la":"Prǽbeant nobis, Dómine, divínum tua sancta fervórem: quo eórum páriter et actu delectémur et fructu."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et ad benefícia recolénda, quibus nos instauráre dignátus es, tríbue veníre gaudéntes."},{"k":"macro","name":"Per Dominum"}],"Munda Cor Passionis":[{"k":"text","la":"Munda cor meum ac lábia mea, omnípotens Deus, qui lábia Isaíæ Prophétæ cálculo mundásti igníto: ita me tua grata miseratióne dignáre mundáre, ut sanctum Evangélium tuum digne váleam nuntiáre. Per Christum, Dóminum nostrum. Amen."},{"k":"text","la":"Jube, domne, benedícere.","mark":"D"},{"k":"text","la":"Dóminus sit in córdibus vestris et in lábiis vestris: ut digne et competénter annuntiétis Evangélium suum: In nómine Patris, et Fílii, + et Spíritus Sancti.","mark":"S"},{"k":"text","la":"Amen.","mark":"D"}]},"hr":{"d5bfabc871d25531":{"t":"Ps 34, 1-2, Ps 34, 3\n(Ps 34, 1-2) Sudi, Gospodine, one koji mi škode, udari one koji udaraju na me. Uzmi oružje i štit i ustani meni u pomoć, Gospodine, snago spasenja mojega. (Ps 34, 3) Potegni koplje i presjeci put onima koji me progone. Reci mojoj duši: Ja sam tvoje spasenje. (Ps 34, 1-2) Sudi, Gospodine, one koji mi škode, udari one koji udaraju na me. Uzmi oružje i štit i ustani meni u pomoć, Gospodine, snago spasenja mojega. [u vremenu Muke ne govori se Slava Ocu u sklopu Ulazne pjesme]","kn":"(Ps. 34, 1, 2). Sudi, Gospodine, one, što mi sude, udari one, koji udaraju na me. Uzmi oružje i šiti i dig.iii se meni u pomoć. Gospodine, silo spasenja mojega. (Ps. 34, 3) Potegni koiplje, i presijeci put onima, koji me gone, reci duši mojoj: Ja sam spasenje tvoje. Sudi, Gospodine.","knRef":"Kniewald 1942, str. 226–227 (snimka 114) (OCR)"},"bca8009d1ebe73a5":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da mi koji zbog svoje slabosti u tolikim suprotivštinama iznemažemo, odahnemo posredovanjem muke Jedinorođenoga tvoga Sina:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj, molimo, svemogući Bože, da mi, koji zbog svoje nejakosti u tolikim suprotlvštinama iznemažemo, odahnemo posredovanjem muke Jedinorođenoga Tvoga, ko ji s Tobom živi ...","knRef":"Kniewald 1942, str. 226–227 (snimka 114) (OCR)"},"64e87927b6660d33":{"t":"Iz 50, 5-10\nČitanje Izaije Proroka. U one dane reče Izaija: Gospodin Bog otvori mi uho a ja se ne protivih niti odstupih natrag. Tijelo svoje predadoh onima koji biju i obraze svoje onima koji tuku, ne odvratih svojega lica od onih koji me ruže i pljuvaju na me. Gospodin je Bog pomoćnik moj, zato se nisam smeo. I zato stavih svoje lice kao pretvrdi kamen i znam da se neću smesti. Blizu je onaj koji me opravdava. Tko će mi se protiviti? Neka pristupi k meni. Gle! Gospodin je Bog pomoćnik moj. Tko će me osuditi? Gle, svi će se kao odjeća poderati, moljac će ih izgristi. Tko se među vama boji Gospodina i sluša glas njegova sluge? Tko ide po mraku i nema svjetla neka se uzda u ime Gospodnje i neka se oslanja na Boga svojega.","kn":"Čitanje Izaije proroka (50, 5-10). U one dane reče Izaija: Gospodin Bog otvori mi uho, a ja se ne pro- 1 tivih, niti odstuipih natrag. Tijelo svoje predadoh onima, koji biju, i obraze svoje onima, koji skubu: ne odvratih lica svojega od onih, koji me ruže i pljuvaju na me. Gospodin je Bog pomoćnik moj, zato ( se nijesam smeo; 1 zato stavili lice svoje kao pretvrdi kamen, i znam, da se ne ću smesti. Blizu je onaj, koji me opravdava, ko će mi se protiviti? Neka pristupi k meni. Gle! Gospodin je Bog pomoćnik moj: i ko je da me osudi? Gle, svi će se kao odjeća odrijeti, grižnja će ih izgristi. Ko se među vama boji Giospodlna, i sluša glas sluge njegova? Ko ide PO mraku i nema svijetla, neka se uzda u ime Gospodnje. i neka se oslanja na Boga svojega.","knRef":"Kniewald 1942, str. 226–227 (snimka 114) (OCR)"},"adb26867ed6caac0":{"t":"Ps 34, 23 i 3\nUstani, Gospodine, i pripazi na moj sud, Bože moj i Gospodine moj, na moju parnicu. Potegni koplje i presjeci put onima koji me progone.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega.","kn":"(Ps. 34, 23, 3). Ustani Gospodine, i prijpazi na sud moj. Bože moj i Gospodine moj, na parnicu moju. Potegni koplje i presijeci put onima, koji me gone.\n\n(Ps. 102, 10). Gospodine, ne postupaj s nama po grijesima našim i ne vraćaj nam po nepravdama našim. (Ps. 78, 8, 9) Gospodine, ne opominji se pređašnjih bezakonja naših, već neka nas brzo preteče milosrđe Tvoje, jer smo postali veoma ubogi (Ovdje se poklekne.) Pomozi nam. Bože, spasitelju naš, i radi slave imena svoga izbavi nas. Gospodine, i očisti nas od grijeha naših radi imena svoga.","knRef":"Kniewald 1942, str. 228–229 (snimka 115) (OCR)"},"7be6be27d6f816c7":{"t":"Iv 12, 1-9\nSlijedi sveto Evanđelje po Ivanu. Šest dana prije Pashe dođe Isus u Betaniju, gdje je bio Lazar što je umro, i koga je Isus oživio od mrtvih. A ondje mu zgotoviše večeru i Marta je služila, a Lazar je bio jedan od onih što su sjedili s njime za stolom. Tada Marija uze litru prave nardove dragocjene pomasti i pomaza Isusove noge i otare svojom kosom njegove noge. A kuća se napunila mirisa od pomasti. Tada kaže jedan od učenika njegovih Juda Iskariotski koji ga je imao izdati: Zašto se ova pomast nije prodala za trista dinara i zašto se nije dala siromasima? A ovo ne reče što bi se brinuo za siromahe, nego što je bio tat i što je imao kesu i nosio što se u nju metalo. Ali Isus reče: Ostavi je da to čini za dan moga ukopa! Jer siromaha imate svagda sa sobom, a mene nemate svagda. Dozna pak vrlo mnogo židovskoga svijeta da je ondje i dođoše ne samo poradi Isusa nego da vide i Lazara koga je uskrisio od mrtvih.","kn":"t Slijedi sv. evanđelje po Ivanu (12, 1-9). Šest dana prije pashe dođe Isus u Betaniju, gdje je bio Lazar, što je umro, i koga je Isus oživio od mrtvih. A ondje mu zgotoviše večeru, i Marta je služila, a Lazar ije bio jedan od onih, što su sjedjeli s njime za stolom. Tada Marija uze litru prave nardove dragocjene pomasti i pomaza Isusove noge i otare svojom kosom njegove noge; i kuća se napunila mirisa od pomasti. Tada kaže jedan od učenika njegovih, Juda Iškariotski, koji ga je imao izdati: Zašto se ova pomast nije prodala za trista dinara, i zašto se nije dala siromasima? A ovo ne reče, što bi se brinuo za siromahe, nego što je bio tat, i što je imao kesu, i nosio, što se u nju metalo. Ali Isus reče; Ostavi je. da to čini na dan ukopa moga! Jer siromaha imadete svagda za sobom, a mene nemate svagda!. Dozna pak vrlo mniOgo židovskoga svijeta, da je ondje, i dođoše ne samo poradi Isusa, nego da vide i Lazara, koga je uskrisio od mrtvih.","knRef":"Kniewald 1942, str. 228–229 (snimka 115) (OCR)"},"24b0f0e6863984cc":{"t":"Ps 95, 11 i 13\nIzbavi me, Gospodine, od mojih neprijatelja. K tebi se utječem, nauči me vršiti tvoju volju, jer si ti Bog moj.","kn":"Izbavi me od neprijatelja mojih, Gospodine, k tebi se utječem, nauči me vršiti volju Tvoju, jer si ti Bog moj.","knRef":"Kniewald 1942, str. 866–867 (snimka 434) (OCR)"},"1998c9bb9d87c519":{"t":"Ove žrtve, svemogući Bože, neka učine da moćnom krepošću očišćeni čistiji dođemo k njihovu početniku.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ove žrtve, svemogući Bože, neka učine, da moćnom krepošću očišćeni, čišći dođemo k njihovom početniku. Gospodinu našem . . .","knRef":"Kniewald 1942, str. 228–229 (snimka 115) (OCR)"},"f2fb1fe68f386b18":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti si odredio spasenje ljudskog roda po drvu Križa, da se opet rodi život ondje gdje je nikla smrt, i onaj koji je na drvu pobijedio, bude pobijeđen na drvu po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glas primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu_ je dostojno i pravedno, pravo i. spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, po Kristu, 1 Gospodinu: našemu: jer Ti si ustanovio spase- I nje ljudskog roda na drvetu križa, da odanle us krsne život, odakle je proizašla smrt, te onaj, koji je na drvetu iznio pobjedu, na drvetu bude i svla- J dan po Kristu, Gospodinu našem, po kojem veličan stvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te i nebeske moći i blaženi Serafini zajedno slave, Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"8d42742f50a875e9":{"t":"Ps 34, 26\nNeka se zastide i zasrame zajedno koji se raduju radi moje nesreće. Neka pokrije stid i sram one koji zlo govore o meni.","kn":"(Ps. 34, 26). Neka se postide i posrame zajedno, koji se raduju radi moje nesreće; neka se ogrnu stidom i sramotom, koji zlo govore na me.","knRef":"Kniewald 1942, str. 228–229 (snimka 115) (OCR)"},"9d873aa39c5de148":{"t":"<i>Pomolimo se</i>.\nNapunila nas, Gospodine, tvoja sveta otajstva božanskim žarom, te uživali i u njihovu vršenju i plodu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prožele nas, Gospodine, Tvoje svetinje božanskim žarom, te uživamo i u njihovu vršenju i plodu, po G. n.","knRef":"Kniewald 1942, str. 358–359 (snimka 180) (OCR)"},"b94e3727cc0432c1":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nPomozi nam, Bože, spasitelju naš, i podaj da se radosno spominjemo tvojih dobročinstava kojima si nas se udostojio preporoditi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Pomozi nam. Bože, spasitelju naš i podaj, da se raidosno spominjemo Tvojih dobročinstava, kojima si nas se udostojio preporoditi, ip,o G. n.","knRef":"Kniewald 1942, str. 228–229 (snimka 115) (OCR)"}}});
